  {
    "target": [ "e1" ],
    "entities": [
      { "id": "e1", "type": "Movie" },
      { "id": "e2", "type": "Actor" },
      { "id": "e3", "type": "Location" }
    ],
    "relationships": [
      { "id": "r1", "role": "acted_in", "from": "e2", "to": "e1" },
      { "id": "r2", "role": "from", "from": "e2", "to": "e3" }
    ],
    "constraint": {
      "list": {
        "list": { "list_elements": "e2" },
        "condition": {
          "left": { "attribute_name": "name", "of": "e3" },
          "operator": "=",
          "right": "Oviedo"
        },
        "quantifier_kind": "EXISTS"
      }
    },
    "distinct": true
  }
]
```

Actually, the standard way to express "at least one actor is from Oviedo" where 'from' is a relationship:

```json
[
  {
    "target": [ "e1" ],
    "entities": [
      { "id": "e1", "type": "Movie" },
      { "id": "e2", "type": "Actor" },
      { "id": "e3", "type": "Location" }
    ],
    "relationships": [
      { "id": "r1", "role": "acted_in", "from": "e2", "to": "e1" },
      { "id": "r2", "role": "is_from", "from": "e2", "to": "e3" }
    ],
    "constraint": {
      "and_conditions": [
        {
          "left": { "attribute_name": "name", "of": "e3" },
          "operator": "=",
          "right": "Oviedo"
        },
        {
          "list": {
            "list": { "list_elements": "e2" }
          },
          "condition": {
            "left": { "attribute_name": "name", "of": "e3" },
            "operator": "=",
            "right": "Oviedo"
          },
          "quantifier_kind": "EXISTS"
        }
      ]
    },
    "distinct": true
  }
]
```

